insert into public.pm_rounds (number, published_at, medium_url, summary, selected_pitch_id) values (5, '2026-10-07', 'https://medium.com/oregon-blockchain-group/oregon-blockchain-group-prediction-markets-5-d266c8cd9cfc', 'September CPI''s 3.6% bucket is overpriced, Gemini isn''t taking #1 in six days, and Trump''s approval dips into 38.2–38.4%.', 'p5-econ-cpi-36') on conflict (number) do nothing;
insert into public.pm_rounds (number, published_at, medium_url, summary, selected_pitch_id) values (6, '2026-10-14', 'https://medium.com/oregon-blockchain-group/oregon-blockchain-group-prediction-markets-6-00edb860a50c', 'Bitcoin holding $82k, Q3 GDP beating 3.5% on GDPNow, and a tighter Brazil runoff.', 'p6-ai-btc-82k') on conflict (number) do nothing;
insert into public.pm_rounds (number, published_at, medium_url, summary, selected_pitch_id) values (7, '2026-10-21', 'https://medium.com/oregon-blockchain-group/oregon-blockchain-group-prediction-markets-7-e9b146348a37', 'Fading Anthropic for best AI model at month-end, Q3 GDP clearing 3.0%, and a Texas split ticket.', 'p7-ai-anthropic') on conflict (number) do nothing;
insert into public.pm_rounds (number, published_at, medium_url, summary, selected_pitch_id) values (8, '2026-10-29', 'https://medium.com/oregon-blockchain-group/oregon-blockchain-group-prediction-markets-8-4fab3fc07174', 'All-midterms round: fading the blue mega-tsunami, Talarico winning Texas, and the Texas Senate landing within three points.', 'p8-politics-mega-tsunami') on conflict (number) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p5-econ-cpi-36', 5, 'economics', 'Nick Sakys', 'September Inflation US — Annual (CPI-U, Unadjusted)', '3.6%', 'synthesis', 'polymarket', array['will-annual-inflation-be-3pt6-in-september-2026']::text[], 'NO', 0.53, 1, 0.62, null, null, '2026-10-14', null, null, array['A 0.1pp-wide bucket priced near 49% implies a forecast error of only 0.07–0.08pp, tighter than the ~0.09–0.10pp average miss of both Street consensus and the Cleveland Fed. A bottom-up build from gas prices and CPI-U weights gives ~41% for 3.6%; a track-record-weighted blend gives ~35%.', 'Core (79% of the basket) and energy decide the bucket, and a small miss either way lands on 3.5% or 3.7%, where NO wins. Plan: hold to the Oct 14 print (~89% return) or limit sell at 62% (~17%) if the price corrects first.']::text[], 'closed', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p5-ai-gemini-top', 5, 'ai_tech', 'Matthew Stone', 'Top AI Model on October 12 (LMSYS Chatbot Arena)', 'Gemini', 'kalshi', 'kalshi', array['KXTOPMODEL-26OCT12-GEMI']::text[], 'NO', 0.26, 1, null, null, null, '2026-10-12', null, null, array['The market priced Gemini jumping from 4th–5th to #1 in six days. Claude held the top four ranks at 1506+ Elo with Gemini 10–15 points back, and at ~800–1,000 votes/day a new model would still be preliminary by Oct 12.', 'Gemini 4 Argon was corporate-access only and regulatory pressure favored measured releases. Plan: sell near 50–60¢ as the market cools, or hold to resolution (~285%).']::text[], 'closed', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p5-politics-trump-approval', 5, 'politics', 'Shaurya Saxena', 'Trump''s Approval Rating on October 9 (RCP)', '38.2–38.4%', 'kalshi', 'kalshi', array['KXAPRPOTUS-26OCT09-38.3']::text[], 'YES', 0.3, 1, null, null, null, '2026-10-09', null, null, array['RCP had approval at ~38.5%, just above the range, so only a 0.1–0.3pp drift down was needed. Lower readings from NYT and Silver Bulletin added downward pressure, and the average had slid ~1pp since Sept 22.', 'With three days to close and no major catalyst before the Oct 14 CPI, the range looked underpriced at 30%. Plan: hold to resolution (~233%).']::text[], 'closed', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p6-ai-btc-82k', 6, 'ai_tech', 'Nick Sakys', 'Bitcoin Above ___ on October 16 (12PM ET)', '$82,000', 'polymarket', 'polymarket', array['bitcoin-above-82000-on-october-16-2026-12pm-et']::text[], 'YES', 0.7, 1, null, null, null, '2026-10-16', null, null, array['Deribit options priced a close above $82,000 at about 75% versus 70% on a thin prediction market book, a gap between professional market makers and roughly $1,000 of volume.', 'DVOL near the 10th percentile of its history implied a calm round with BTC 1.5% above the strike, and the Oct 14 CPI print looked more likely to be neutral-to-supportive. Plan: hold to resolution.']::text[], 'closed', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p6-econ-gdp-35', 6, 'economics', 'Carsen Luna', 'US Real GDP Growth in Q3 2026', 'Above 3.5%', 'kalshi', 'kalshi', array['KXGDP-26OCT30-T3.5']::text[], 'YES', 0.36, 0.52, 0.52, null, 0.25, '2026-10-27', null, null, array['The market priced >3.5% at 36%, much closer to the NY Fed nowcast (2.65%) than to Atlanta Fed GDPNow (3.6%). GDPNow is built bottom-up from hard data the way BEA computes GDP and has the better real-time track record (RMSE ~1.17pp vs ~1.6pp), implying roughly a 52% chance.', 'Four scheduled releases before the Oct 27 exit give the market reasons to reprice toward GDPNow. Sell limit at 52% (~44% return); stop at 25% (~31% loss) if weak data pulls GDPNow below 3%.']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p6-politics-brazil-margin', 6, 'politics', 'Audrey Hudspeth', 'Brazil Presidential Election Second Round: Margin of Victory', 'Flávio Bolsonaro <4%', 'synthesis', 'polymarket', array['will-flavio-bolsonaro-win-the-second-round-of-the-2026-brazilian-presidential-election-by-less-than-4']::text[], 'YES', 0.35, 1, 0.5, '2026-10-25', null, null, null, null, array['All three Oct 13 polls showed Flávio up 4 points or less (average +3.2), and he won the first round by just 1.87 points, yet the market favored a 4–8 point win.', 'The Oct 18 and 23 debates add pressure: Lula is a veteran debater while Flávio has a thin record. Plan: limit sell at 50¢ before Oct 25 (~43% return).']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p7-ai-anthropic', 7, 'ai_tech', 'Charlie Sneed', 'Which Company Has the Best AI Model at the End of October?', 'Anthropic', 'polymarket', 'polymarket', array['will-anthropic-have-the-best-ai-model-at-the-end-of-october-2026-20260811194841118']::text[], 'NO', 0.82, 1, null, null, 0.65, '2026-10-31', null, null, array['The market resolves on Arena''s Text leaderboard, where Gemini 4 Argon has led since Oct 2 and Claude Opus 5.5 sits 16 points back despite twice the votes. Anthropic would need a new model that beats Argon within eleven days, and nothing is announced or leaked.', 'Main risk is Argon''s score sliding as new public votes land. Plan: hold to Oct 31 (~22%); exit at a 65¢ stop (~21% loss) if Argon''s lead drops under ten points.']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p7-econ-gdp-30', 7, 'economics', 'Matthew Stone', 'US Real GDP Growth in Q3 2026', 'Above 3.0%', 'kalshi', 'kalshi', array['KXGDP-26OCT30-T3.0']::text[], 'YES', 0.7, 1, 0.8, null, 0.55, '2026-10-29', null, null, array['GDPNow tracks Q3 at 3.5%, and its ~1.17pp historical error implies roughly a 67% chance of clearing 3.0%. Goldman is at 3.1% and September industrial production rose 0.7%; the big net-exports drag is already in both estimates.', 'Inventories supply about half the growth and are volatile, so the Oct 28 inventory/trade report is the key risk. Plan: sell near 80¢ (~14%), stop at 55¢ (~21% loss).']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p7-politics-texas-split', 7, 'politics', 'Shaurya Saxena', 'Texas Senate and Governor Combo', 'Reps win Gov, Dems win Senate', 'polymarket', 'polymarket', array['will-republicans-win-the-texas-governor-election-and-democrats-win-the-texas-senate-election-20260804162614416']::text[], 'YES', 0.46, 1, null, null, null, '2026-11-03', null, null, array['Talarico has led Paxton in nearly every recent poll (NYT 51–45, even Trafalgar has him ahead) with strong independent support and competitive spending.', 'Abbott edges Hinojosa on border security, public safety, and property taxes, outspent him 6-to-1, and leads among older, high-turnout voters. Plan: hold to Election Day (~117%).']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p8-politics-mega-tsunami', 8, 'politics', 'Jared Vaughn', 'Blue Mega-Tsunami in 2026?', 'Dems win 54+ Senate and 240+ House', 'polymarket', 'polymarket', array['blue-mega-tsunami-in-2026']::text[], 'NO', 0.79, 1, 0.97, null, null, '2026-11-03', null, null, array['The Senate threshold is the obstacle: Democrats caucus 47, so 54 needs seven net pickups. Even winning NC, ME, AK, OH, and TX only gets to 52 while holding every seat. A strong Democratic night can still miss the combined bar.', 'Thin leads leave room for Republican consolidation (Texas flips to a tie if a third of Libertarian support moves to Paxton), and Iowa shows a six-point split between Democratic candidates in one poll. Plan: hold to resolution (~26.6%) or limit sell at 97¢ (~22.8%).']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p8-politics-talarico', 8, 'politics', 'Audrey Hudspeth', 'Texas Senate Election Winner', 'James Talarico (D)', 'polymarket', 'polymarket', array['will-the-democrats-win-the-texas-senate-race-in-2026']::text[], 'YES', 0.68, 1, null, null, null, '2026-11-03', null, null, array['Paxton is a damaged nominee: impeached in 2023, 41/57 favorability (worst statewide), and tied to a president 54% of Texas likely voters view unfavorably.', 'Talarico leads every major average by 1.8–4.3 points, wins independents 60–32, and early voting is up 74% with Democratic counties leading. Plan: hold to resolution (~47%).']::text[], 'open', null) on conflict (id) do nothing;
insert into public.pm_pitches (id, round_number, sector, analyst, market_title, outcome_label, venue, market_source, market_ids, side, entry_price, implied_price, sell_limit, sell_limit_before, stop_loss, exit_by, exit_price, exited_at, thesis, status, recorded_votes) values ('p8-politics-tx-margin', 8, 'politics', 'Clayton Fawthrop-Male', 'Texas Senate Election Margin of Victory', 'Talarico 0–3% or Paxton 0–3%', 'polymarket', 'polymarket_basket', array['will-the-democratic-party-candidate-win-the-2026-texas-senate-election-by-0-3', 'will-the-republican-party-candidate-win-the-2026-texas-senate-election-by-0-3']::text[], 'YES', 0.51, 1, null, null, null, '2026-11-03', null, null, array['Polls average Talarico +2 and early voters split 33.3% Democratic-primary vs 32.7% Republican-primary; in 2022 that early-vote gap landed within ~2 points of the final margin.', '2018 Cruz–O''Rourke polled Cruz +6 but finished +2.6. Bought as Talarico 0–3% (34¢) plus Paxton 0–3% (17¢), sized two-thirds/one-third so either leg pays ~96%.']::text[], 'open', null) on conflict (id) do nothing;
